var scale3 = (a, s) => [a[0] * s, a[1] * s, a[2] * s];
var normalize2 = (a) => scale3(a, 1 / (Math.hypot(a[0], a[1], a[2]) || 1));
var PHI = (1 + Math.sqrt(5)) / 2;
var ICOSAHEDRON_VERTICES = [
  [-1, PHI, 0],
  [1, PHI, 0],
  [-1, -PHI, 0],
  [1, -PHI, 0],
  [0, -1, PHI],
  [0, 1, PHI],
  [0, -1, -PHI],
  [0, 1, -PHI],
  [PHI, 0, -1],
  [PHI, 0, 1],
  [-PHI, 0, -1],
  [-PHI, 0, 1]
].map(normalize2);

