    for (const clone of made4.clones ?? [])
      clones.push({ ...clone, of: named(clone.of), at: inBuild(clone.at), turn: turnOf3(clone.turn) });
    for (const tree2 of made4.trees ?? [])
      trees.push({ ...tree2, at: inBuild(tree2.at), ...Number.isFinite(tree2.turn) && { turn: tree2.turn - turned6 } });
